def revenue_by_customer(rows):
    """Sum each customer's revenue for the month.

    Returns {customer_id: {currency: Decimal}} in major units, quantized to
    4 places. Amounts are kept per currency because rows are not FX-converted.
    """
    totals = {}
    for row in rows:
        by_currency = totals.setdefault(row["customer_id"], {})
        amount = Decimal(row["total_cents"]) / 100
        by_currency[row["currency"]] = by_currency.get(row["currency"], Decimal(0)) + amount
    return {
        customer_id: {
            currency: total.quantize(Decimal("0.0001"))
            for currency, total in by_currency.items()
        }
        for customer_id, by_currency in totals.items()
    }

